    },
    ...restConfig,
    mutationFn: createDiscussion,
  });
};

import { Button } from '@/components/ui/button';
import { ConfirmationDialog } from '@/components/ui/dialog';
import { useNotifications } from '@/components/ui/notifications';
import { useUser } from '@/lib/auth';

import { useDeleteUser } from '../api/delete-user';

type DeleteUserProps = {
  id: string;
};

export const DeleteUser = ({ id }: DeleteUserProps) => {
  const user = useUser();
  const { addNotification } = useNotifications();
  const deleteUserMutation = useDeleteUser({
    mutationConfig: {
      onSuccess: () => {
        addNotification({
          type: 'success',
          title: 'User Deleted',
        });
      },
    },
  });

  if (user.data?.id === id) return null;

  return (
    <ConfirmationDialog
      icon="danger"
      title="Delete User"
      body="Are you sure you want to delete this user?"
      triggerButton={<Button variant="destructive">Delete</Button>}
      confirmButton={
        <Button
          isLoading={deleteUserMutation.isPending}
          type="button"
          variant="destructive"
          onClick={() => deleteUserMutation.mutate({ userId: id })}
        >
          Delete User
        </Button>
      }
    />
  );
};

import { useNotifications } from '@/components/ui/notifications';
import { cn } from '@/utils/cn';

import { useUpdateUserRole } from '../api/update-user-role';

type UpdateUserRoleProps = {
  userId: string;
  initialRole: 'ADMIN' | 'USER';
};

export const UpdateUserRole = ({ userId, initialRole }: UpdateUserRoleProps) => {
  const { addNotification } = useNotifications();
  const updateUserRoleMutation = useUpdateUserRole({
    mutationConfig: {
      onSuccess: () => {
        addNotification({
          type: 'success',
          title: 'Role Updated',
        });
      },
    },
  });

  const handleRoleChange = (newRole: 'ADMIN' | 'USER') => {
    updateUserRoleMutation.mutate({ userId, role: newRole });
  };

  return (
    <select
      value={initialRole}
      onChange={(e) => handleRoleChange(e.target.value as 'ADMIN' | 'USER')}
      disabled={updateUserRoleMutation.isPending}
      className={cn(
        'rounded-md border border-gray-300 bg-white py-1 pl-2 pr-8 text-sm focus:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500',
        updateUserRoleMutation.isPending && 'opacity-50',
      )}
    >
      <option value="ADMIN">ADMIN</option>
      <option value="USER">USER</option>
    </select>
  );
};

